struct ObjectDistance: Equatable { let id: Int; let distance: Int }
func distances(_ values: [ObjectDistance]) -> String { let text = values.map { "\($0.id):\($0.distance)" }.joined(separator: " "); return text.isEmpty ? "-" : text }
